CREATE TABLE settlement_guard(user_id BIGINT PRIMARY KEY);
CREATE TABLE ledger_account(id VARCHAR(80) PRIMARY KEY,owner_id BIGINT NOT NULL,bucket VARCHAR(24) NOT NULL,balance_cent BIGINT NOT NULL DEFAULT 0,version BIGINT NOT NULL DEFAULT 0,updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE(owner_id,bucket),CHECK(bucket IN('FROZEN','AVAILABLE','PAYOUT_PENDING','DEBT','REVENUE','CHANNEL_FEE','CHANNEL')),CHECK(owner_id=0 OR bucket='DEBT' OR balance_cent>=0));
CREATE TABLE ledger_journal(id CHAR(36) PRIMARY KEY,business_key VARCHAR(150) NOT NULL UNIQUE,kind VARCHAR(32) NOT NULL,reference_id VARCHAR(64) NOT NULL,source_event CHAR(36) NULL,payload_hash CHAR(64) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX ix_journal_reference(reference_id,created_at));
CREATE TABLE ledger_entry(journal_id CHAR(36) NOT NULL,account_id VARCHAR(80) NOT NULL,delta_cent BIGINT NOT NULL,balance_after_cent BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(journal_id,account_id),FOREIGN KEY(journal_id) REFERENCES ledger_journal(id),FOREIGN KEY(account_id) REFERENCES ledger_account(id),INDEX ix_entry_account(account_id,created_at),CHECK(delta_cent<>0));
CREATE TABLE earning_freeze(order_id CHAR(36) PRIMARY KEY,user_id BIGINT NOT NULL,amount_cent BIGINT NOT NULL,release_at TIMESTAMP(6) NOT NULL,status VARCHAR(16) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),released_at TIMESTAMP(6) NULL,FOREIGN KEY(order_id) REFERENCES business_order(id),CHECK(status IN('FROZEN','RELEASED','REVERSED')),INDEX ix_freeze_due(status,release_at));
CREATE TABLE withdrawal_account(user_id BIGINT PRIMARY KEY,display_name VARCHAR(120) NOT NULL,provider_account VARCHAR(200) NOT NULL,updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6));
CREATE TABLE withdrawal(id CHAR(36) PRIMARY KEY,user_id BIGINT NOT NULL,idempotency_key VARCHAR(100) NOT NULL,request_hash CHAR(64) NOT NULL,provider VARCHAR(16) NOT NULL,account_snapshot JSON NOT NULL,amount_cent BIGINT NOT NULL,rule_version INT NOT NULL,status VARCHAR(24) NOT NULL,channel_id VARCHAR(128) NULL UNIQUE,last_error VARCHAR(500) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE(user_id,idempotency_key),FOREIGN KEY(rule_version) REFERENCES fee_rule(version),CHECK(amount_cent>0),CHECK(status IN('PENDING','PROCESSING','SUCCEEDED','FAILED')),INDEX ix_withdrawal_user(user_id,created_at),INDEX ix_withdrawal_pending(status,updated_at));
CREATE TABLE mock_channel_withdrawal(withdrawal_id CHAR(36) PRIMARY KEY,amount_cent BIGINT NOT NULL,status VARCHAR(24) NOT NULL,channel_id VARCHAR(128) NOT NULL UNIQUE,account_hash CHAR(64) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE reconciliation_batch(id CHAR(36) PRIMARY KEY,provider VARCHAR(16) NOT NULL,bill_date DATE NOT NULL,bill_hash CHAR(64) NOT NULL,status VARCHAR(24) NOT NULL,source VARCHAR(24) NOT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),completed_at TIMESTAMP(6) NULL,UNIQUE(provider,bill_date,bill_hash),CHECK(status IN('RUNNING','COMPLETED','FAILED')));
CREATE TABLE reconciliation_difference(id CHAR(36) PRIMARY KEY,batch_id CHAR(36) NOT NULL,record_type VARCHAR(16) NOT NULL,reference_id VARCHAR(64) NOT NULL,kind VARCHAR(40) NOT NULL,status VARCHAR(24) NOT NULL,details JSON NOT NULL,resolution VARCHAR(500) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(batch_id) REFERENCES reconciliation_batch(id),UNIQUE(batch_id,record_type,reference_id,kind),CHECK(status IN('OPEN','REPAIRED','ACKNOWLEDGED')),INDEX ix_difference_open(status,created_at));
CREATE TRIGGER ledger_journal_no_update BEFORE UPDATE ON ledger_journal FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Journal is immutable';
CREATE TRIGGER ledger_journal_no_delete BEFORE DELETE ON ledger_journal FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Journal is immutable';
CREATE TRIGGER ledger_entry_no_update BEFORE UPDATE ON ledger_entry FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Ledger entry is immutable';
CREATE TRIGGER ledger_entry_no_delete BEFORE DELETE ON ledger_entry FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Ledger entry is immutable';
CREATE TABLE commerce_cdc_failure(id CHAR(36) PRIMARY KEY,topic VARCHAR(200) NOT NULL,partition_id INT NOT NULL,offset_id BIGINT NOT NULL,payload MEDIUMTEXT NOT NULL,error_type VARCHAR(200) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',attempts INT NOT NULL DEFAULT 0,next_retry_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE(topic,partition_id,offset_id),INDEX ix_commerce_cdc_retry(status,next_retry_at));
